<div hlmSidebarWrapper>
  <hlm-sidebar>
    <div hlmSidebarHeader>
      <div class="flex items-center gap-2 px-2 py-1.5">
        <ng-icon name="lucideShield" class="text-sidebar-primary size-5" />
        <span class="text-sm font-semibold">Hero Ops Console</span>
      </div>
    </div>

    <div hlmSidebarContent>
      <nav aria-label="Primary">
        <div hlmSidebarGroup>
          <div hlmSidebarGroupLabel>Command</div>
          <div hlmSidebarGroupContent>
            <ul hlmSidebarMenu>
              @for (item of vm.navigation; track item.path) {
                <li hlmSidebarMenuItem>
                  <a
                    hlmSidebarMenuButton
                    [routerLink]="item.path"
                    routerLinkActive
                    #active="routerLinkActive"
                    [isActive]="active.isActive"
                  >
                    <ng-icon [name]="item.icon" />
                    <span>{{ item.label }}</span>
                  </a>
                </li>
              }
            </ul>
          </div>
        </div>
      </nav>
    </div>

    <div hlmSidebarFooter>
      <div class="flex items-center gap-3 px-2 py-1.5">
        <hlm-avatar size="sm">
          <span hlmAvatarFallback>OP</span>
        </hlm-avatar>
        <div class="min-w-0">
          <p class="truncate text-sm font-medium">Operator</p>
          <p class="text-sidebar-muted truncate text-xs">Command desk</p>
        </div>
      </div>
