import { computed, inject, Injectable, signal } from '@angular/core';
import { Router } from '@angular/router';
import { POWER_CLASSES, type HeroStatus, type PowerClass } from '../domain/hero.model';
import { HeroService } from '../domain/hero.service';

export type ClassFilter = PowerClass | 'all';

export interface ClassOption {
  readonly value: ClassFilter;
  readonly label: string;
}

type StatusVariant = 'success' | 'warning' | 'destructive' | 'secondary';

/** One roster line, already shaped for the table: no formatting left to the template. */
export interface RosterRow {
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly initials: string;
  readonly powerClass: PowerClass;
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly statusVariant: StatusVariant;
  readonly clearanceTier: number;
}

/** Status carries meaning, so each one maps to a semantic badge variant. */
const STATUS_VARIANT: Readonly<Record<HeroStatus, StatusVariant>> = {
  Active: 'success',
